```python
def load_tax_rates(path="/etc/billing/tax_rates.json"):
    try:
        with open(path) as f:
            return json.load(f)
    except Exception as e:
        log.warning("could not load tax rates: %s", e)
        return {}

RATES = load_tax_rates()

def tax_for(order):
    rate = RATES.get(order.region, 0)
    return (order.subtotal * Decimal(str(rate))).quantize(Decimal("0.01"))
```

